  1→//! Layer sync integration tests
  2→//!
  3→//! Focused tests for static and dynamic channel layer sync using group-chat app.
  4→//! Tests cover: owner→node, owner→node→viewer, dynamic layer creation,
  5→//! second message propagation, viewer writes, and late joiners.
  6→
  7→use std::time::Duration;
  8→
  9→use anyhow::Result;
 10→use tokio::time::sleep;
 11→use serde_json::Value;
 12→use tracing::info;
 13→
 14→use butler::ScribeMessage;
 15→use crate::fixtures::{init_tracing, wait_for_layer_data};
 16→use crate::peer::Peer;
 17→use crate::scenario::Scenario;
 18→
 19→async fn get_layer_json(peer: &Peer, page_id: &str, layer_name: &str) -> Result<Value> {
 20→    let scribe = peer.butler.open_page(page_id).await?;
 21→    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
 22→    scribe
 23→        .cast(ScribeMessage::GetLayerData {
 24→            layer_name: layer_name.to_string(),
 25→            reply: reply_tx,
 26→        })
 27→        .map_err(|e| anyhow::anyhow!("GetLayerData cast failed: {:?}", e))?;
 28→
 29→    reply_rx
 30→        .await
 31→        .map_err(|_| anyhow::anyhow!("GetLayerData channel closed"))?
 32→        .map_err(|e| anyhow::anyhow!("GetLayerData failed: {}", e))
 33→}
 34→
 35→/// Poll `get_layer_json` until a specific key appears in the map.
 36→async fn wait_for_layer_json_key(
 37→    peer: &Peer,
 38→    page_id: &str,
 39→    layer_name: &str,
 40→    key: &str,
 41→    timeout: Duration,
 42→) -> Result<Value> {
 43→    let deadline = tokio::time::Instant::now() + timeout;
 44→    loop {
 45→        if let Ok(json) = get_layer_json(peer, page_id, layer_name).await {
 46→            if let Some(val) = json.get(key) {
 47→                return Ok(val.clone());
 48→            }
 49→        }
 50→        if tokio::time::Instant::now() > deadline {
 51→            return Err(anyhow::anyhow!(
 52→                "Timeout waiting for key '{}' in layer '{}' on page '{}'",
 53→                key, layer_name, page_id
 54→            ));
 55→        }
 56→        tokio::time::sleep(Duration::from_millis(50)).await;
 57→    }
 58→}
 59→
 60→/// Static channel (channels/general/messages) syncs from owner to node.
 61→#[tokio::test]
 62→async fn test_static_channel_syncs_owner_to_node() -> Result<()> {
 63→    init_tracing();
 64→
 65→    let mut s = Scenario::builder()
 66→        .app("group-chat")
 67→        .published()
 68→        .build()
 69→        .await?;
 70→
 71→    let page_id = s.space().page_id.clone();
 72→    sleep(Duration::from_millis(500)).await;
 73→
 74→    let owner_scribe = s.owner().butler.open_page(&page_id).await?;
 75→
 76→    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
 77→    owner_scribe.cast(ScribeMessage::EnsureLoroMap {
 78→        layer_name: "channels/general/messages".to_string(),
 79→        reply: reply_tx,
 80→    }).map_err(|e| anyhow::anyhow!("EnsureLoroMap failed: {:?}", e))?;
 81→    reply_rx.await??;
 82→
 83→    owner_scribe.cast(ScribeMessage::MapInsert {
 84→        layer_name: "channels/general/messages".to_string(),
 85→        path: String::new(),
 86→        key: "msg1".to_string(),
 87→        value: serde_json::json!({
 88→            "id": "msg1",
 89→            "text": "Hello from owner",
 90→            "sender_did": "did:key:owner",
 91→            "timestamp": 1234567890
 92→        }),
 93→    }).map_err(|e| anyhow::anyhow!("MapInsert failed: {:?}", e))?;
 94→
 95→    let node_data = wait_for_layer_data(
 96→        &s.node().butler,
 97→        &page_id,
 98→        "channels/general/messages",
 99→        Duration::from_secs(10),
100→    ).await?;
101→
102→    assert!(!node_data.is_empty(), "Node should receive static channel layer data");
103→
104→    s.shutdown().await;
105→    Ok(())
106→}
