121→    let space_id = s.space().space_id.clone();
122→    sleep(Duration::from_millis(500)).await;
123→
124→    // Owner writes BEFORE viewer connects
125→    let owner_scribe = s.owner().butler.open_page(&page_id).await?;
126→
127→    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
128→    owner_scribe.cast(ScribeMessage::EnsureLoroMap {
129→        layer_name: "channels/general/messages".to_string(),
130→        reply: reply_tx,
131→    }).map_err(|e| anyhow::anyhow!("EnsureLoroMap failed: {:?}", e))?;
132→    reply_rx.await??;
133→
134→    owner_scribe.cast(ScribeMessage::MapInsert {
135→        layer_name: "channels/general/messages".to_string(),
136→        path: String::new(),
137→        key: "msg1".to_string(),
138→        value: serde_json::json!({
139→            "id": "msg1",
140→            "text": "Pre-viewer message",
141→            "sender_did": "did:key:owner",
142→            "timestamp": 1234567890
143→        }),
144→    }).map_err(|e| anyhow::anyhow!("MapInsert failed: {:?}", e))?;
145→
146→    // Wait for data on node first
147→    wait_for_layer_data(
148→        &s.node().butler,
149→        &page_id,
150→        "channels/general/messages",
151→        Duration::from_secs(10),
152→    ).await?;
153→
154→    // Connect viewer
155→    let viewer_link = s.get_viewer_link(&space_id).await?;
156→    s.add_viewer(0, &viewer_link, &page_id).await?;
157→
158→    // Viewer should receive the data
159→    let viewer_data = wait_for_layer_data(
160→        &s.viewer(0).butler,
161→        &page_id,
162→        "channels/general/messages",
163→        Duration::from_secs(10),
164→    ).await?;
165→
166→    assert!(!viewer_data.is_empty(), "Viewer should receive static channel data");
167→
168→    s.shutdown().await;
169→    Ok(())
170→}
