172→/// Dynamic channel: first message from owner reaches viewer via node relay.
173→///
174→/// Viewer connects first, then owner creates dynamic layer + writes msg1.
175→#[tokio::test]
176→async fn test_dynamic_channel_first_message_reaches_viewer() -> Result<()> {
177→    init_tracing();
178→
179→    let mut s = Scenario::builder()
180→        .app("group-chat")
181→        .published()
182→        .viewers(1)
183→        .build()
184→        .await?;
