186→    let page_id = s.space().page_id.clone();
187→    let space_id = s.space().space_id.clone();
188→    sleep(Duration::from_millis(500)).await;
189→
190→    // Connect viewer first
191→    let viewer_link = s.get_viewer_link(&space_id).await?;
192→    s.add_viewer(0, &viewer_link, &page_id).await?;
193→    sleep(Duration::from_millis(500)).await;
194→
195→    // Owner creates dynamic layer and writes msg1
196→    let owner_scribe = s.owner().butler.open_page(&page_id).await?;
197→
198→    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
199→    owner_scribe.cast(ScribeMessage::CreateDynamicLayer {
200→        schema_key: "channels/{id}/messages".to_string(),
201→        layer_id: "project-x".to_string(),
202→        reply: reply_tx,
203→    }).map_err(|e| anyhow::anyhow!("CreateDynamicLayer failed: {:?}", e))?;
204→
205→    let full_layer_name = reply_rx.await
206→        .map_err(|_| anyhow::anyhow!("CreateDynamicLayer channel closed"))?
207→        .map_err(|e| anyhow::anyhow!("CreateDynamicLayer failed: {}", e))?;
208→
209→    let bare_layer = full_layer_name
210→        .strip_prefix(&format!("{}/", page_id))
211→        .unwrap_or(&full_layer_name);
