220→            "sender_did": "did:key:owner",
221→            "timestamp": 1234567890
222→        }),
223→    }).map_err(|e| anyhow::anyhow!("MapInsert failed: {:?}", e))?;
224→
225→    // Node should receive it
226→    wait_for_layer_data(
227→        &s.node().butler,
228→        &page_id,
229→        bare_layer,
230→        Duration::from_secs(10),
231→    ).await?;
232→
233→    // Viewer should receive msg1
234→    wait_for_layer_json_key(
235→        s.viewer(0),
236→        &page_id,
237→        bare_layer,
238→        "msg1",
239→        Duration::from_secs(10),
240→    ).await?;
241→
242→    info!("Viewer received msg1 on dynamic channel");
243→
244→    s.shutdown().await;
245→    Ok(())
246→}
