372→/// Apply CRDT update to layer
373→///
374→/// **Context**: Actually merge the update into the layer
375→/// **We do**: Set pending source, apply, clear pending source
376→#[instrument(skip(state, update), fields(page_id = %state.page_id, layer = %layer_name))]
377→fn apply_crdt_update(
378→    state: &mut ScribeState,
379→    layer_name: &str,
380→    update: &[u8],
381→    from_peer: Option<(String, String)>,
382→) -> Result<(), String> {
383→    // Set pending update source BEFORE apply() so observer knows who caused this change
384→    set_pending_update_source(state, from_peer);
385→
386→    // Get the layer and apply update
387→    let result = if let Some(unit) = state.units.get(layer_name) {
388→        unit.layer().apply(update)
389→    } else {
390→        clear_pending_update_source(state);
391→        return Err("Layer not found".to_string());
392→    };
393→
394→    if let Err(e) = result {
395→        // Clear on error too
396→        clear_pending_update_source(state);
397→        error!(error = %e, "Failed to apply update to layer");
398→        return Err(format!("Failed to apply update: {}", e));
399→    }
400→
401→    // Clear pending update source AFTER apply() (observer already captured it)
402→    clear_pending_update_source(state);
403→
404→    Ok(())
405→}
406→
407→/// Handle post-apply actions for remote updates
408→///
409→/// **Context**: Remote update was successfully applied
410→/// **We do**: Flush app layers immediately
411→/// **Note**: UI notification is handled by Loro observer (no duplicate emit here)
412→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
413→async fn handle_post_apply(
414→    state: &mut ScribeState,
415→    layer_name: &str,
416→    _from_peer: Option<(String, String)>,
417→) {
418→    // For app layers, flush immediately to storage so restart loads new code
419→    if layer_name.starts_with("app:") {
420→        if let Some(unit) = state.units.get_mut(layer_name) {
421→            let snapshot = unit.layer().export_snapshot();
422→            if let Err(e) = state.layer_storage.save_layer(layer_name, &snapshot) {
423→                error!(layer = %layer_name, error = %e, "Failed to save app layer immediately");
424→            } else {
425→                info!(layer = %layer_name, "Saved app layer immediately for restart");
426→                // Remove from dirty since we just saved it
427→                unit.clear_dirty();
428→            }
429→        }
430→    }
431→
432→    // Note: UI notification via emit_layer_changed_after_apply was removed
433→    // The Loro observer handles PageUpdate::LayerChanged for all changes (local and remote)
434→    // This prevents duplicate notifications
435→}
