451→/// Get role for a peer from their stored permit
452→///
453→/// **Context**: Determining role for Lua validation
454→/// **Checks**:
455→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
456→/// 2. Stored permit (node mode) -> extract role from permit
457→/// 3. Default -> "peer"
458→#[instrument(skip(state), fields(page_id = %state.page_id))]
459→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
460→    // If peer is our sync target, they are the "node" from our perspective
461→    if let Some(ref config) = state.sync_config {
462→        if let Some(ref sync_target) = config.sync_target {
463→            if sync_target == peer_did {
464→                return "node".to_string();
465→            }
466→        }
467→    }
468→
469→    // Node mode: look up peer's stored permit and extract role via PermitContext
470→    if let Some(ref resolver) = state.peer_resolver {
471→        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
472→            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
473→                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
474→                .unwrap_or_else(|_| "peer".to_string());
475→            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
476→            return role;
477→        }
478→    }
479→
480→    // Default role
481→    "peer".to_string()
482→}
