  1→//! Subscription handling for Scribe actor
  2→
  3→use std::collections::HashMap;
  4→
  5→use tokio::sync::mpsc;
  6→use tracing::{debug, info, warn, instrument};
  7→
  8→use crate::layer_unit::Capabilities;
  9→use crate::message::{BroadcastPayload, EphemeralOutbound};
 10→use crate::state::{ScribeState, SubscriberInfo, normalize_layer_name};
 11→use crate::ephemeral::{emit_peer_subscribed, emit_peer_unsubscribed};
 12→
 13→/// Extract permit holder's DID from the permit's audience field
 14→fn extract_permit_holder_did(permit: &str, fallback_did: &str) -> String {
 15→    match gurkha::Permit::from_token(permit) {
 16→        Ok(parsed) => {
 17→            let raw_aud = parsed.parsed().audience().to_string();
 18→            if raw_aud.starts_with("did:key:") {
 19→                raw_aud
 20→            } else {
 21→                match herald::Identity::did_from_base64_pubkey(&raw_aud) {
 22→                    Ok(did) => did,
 23→                    Err(e) => {
 24→                        warn!(error = %e, raw_aud = %raw_aud, "Failed to convert audience to DID");
 25→                        raw_aud
 26→                    }
 27→                }
 28→            }
 29→        }
 30→        Err(e) => {
 31→            warn!(error = %e, "Failed to extract audience from permit");
 32→            fallback_did.to_string()
 33→        }
 34→    }
 35→}
 36→
 37→/// Handle peer subscription
 38→///
 39→/// Parses permit, stores connection info, adds subscriber to each accessible
 40→/// LayerUnit, sends initial state, and issues pending layer permits.
 41→#[instrument(skip(state, broadcast_tx, ephemeral_tx, permit_token), fields(page_id = %state.page_id))]
 42→pub async fn handle_subscribe(
 43→    state: &mut ScribeState,
 44→    user_did: String,
 45→    device_id: String,
 46→    broadcast_tx: mpsc::Sender<BroadcastPayload>,
 47→    ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
 48→    permit_token: String,
 49→) {
 50→    info!(user_did = %user_did, device_id = %device_id, "Peer subscribing");
 51→
 52→    let permit = match gurkha::Permit::from_token(&permit_token) {
 53→        Ok(p) => p,
 54→        Err(e) => {
 55→            warn!(error = ?e, "Failed to parse permit, rejecting subscription");
 56→            return;
 57→        }
 58→    };
 59→
 60→    let permit_holder_did = extract_permit_holder_did(&permit_token, &user_did);
 61→
 62→    let vectors = match state.vector_storage.load_vectors(&user_did, &device_id) {
 63→        Ok(Some(v)) => v.into_iter()
 64→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
 65→            .collect(),
 66→        Ok(None) => HashMap::new(),
 67→        Err(e) => {
 68→            warn!(error = %e, "Failed to load peer vectors");
 69→            HashMap::new()
 70→        }
 71→    };
 72→
 73→    let is_visible = permit.is_visible();
 74→    let can_see_others = permit.can_see_others();
 75→    let display_name = permit.display_name().map(String::from);
 76→
 77→    info!(
 78→        user_did = %user_did,
 79→        permit_holder_did = %permit_holder_did,
 80→        is_visible = is_visible,
 81→        layers = ?permit.layers().keys().collect::<Vec<_>>(),
 82→        "Subscription with permit"
 83→    );
 84→
 85→    if let Ok(mut subs) = state.subscribers.write() {
 86→        subs.insert(
 87→            (user_did.clone(), device_id.clone()),
 88→            SubscriberInfo {
 89→                permit: permit.clone(),
 90→                subscriber_did: permit_holder_did.clone(),
 91→                is_visible,
 92→                can_see_others,
 93→                display_name: display_name.clone(),
 94→                broadcast_tx: broadcast_tx.clone(),
 95→                ephemeral_tx,
 96→                vectors,
 97→            },
 98→        );
 99→    }
100→
101→    // Add subscriber to each accessible LayerUnit
102→    add_subscriber_to_layers(state, &user_did, &permit, &permit_holder_did, can_see_others, &broadcast_tx);
103→
104→    emit_peer_subscribed(state, &user_did);
105→
106→    send_initial_state_to_subscriber(state, &user_did, &device_id, &broadcast_tx).await;
107→
108→    // __sync_meta bootstrap (node-side only): create and populate the peer's discovery catalog
109→    if state.permit_issuer.is_some() {
110→        bootstrap_sync_meta(state, &permit_holder_did, &permit, &broadcast_tx);
111→    }
112→
113→    // Observability: list which layers this subscriber was added to
114→    let subscribed_layers: Vec<String> = state.units.iter()
115→        .filter(|(_, unit)| unit.can_push_to(&user_did))
116→        .map(|(name, _)| name.clone())
117→        .collect();
118→    state.emit_subscriber_state_capture(
119→        &user_did,
120→        &subscribed_layers,
121→        state.units.len(),
122→        can_see_others,
123→        is_visible,
124→    );
125→}
126→
127→/// Add subscriber to all LayerUnits they have access to (from page permit)
128→fn add_subscriber_to_layers(
129→    state: &ScribeState,
130→    user_did: &str,
131→    permit: &gurkha::Permit,
132→    permit_holder_did: &str,
133→    can_see_others: bool,
134→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
135→) {
136→    for (layer_name, unit) in &state.units {
137→        if unit.is_local_only() { continue; }
138→
139→        if (layer_name == "presence" || layer_name.ends_with("/presence")) && !can_see_others {
140→            continue;
141→        }
142→
143→        if permit.sync_facts().no_incoming_updates.contains(&layer_name.to_string()) {
144→            continue;
145→        }
146→
147→        if permit.can_read_layer(layer_name, &state.page_id, permit_holder_did) {
148→            let can_write = permit.can_write_layer(layer_name, &state.page_id, permit_holder_did);
149→            let caps = Capabilities { read: true, write: can_write, sync: true };
150→            unit.add_subscriber(user_did.to_string(), caps, broadcast_tx.clone());
151→            state.emit_layer_auth_capture(layer_name, user_did, "subscriber_added_page_permit");
152→        }
153→    }
154→}
155→
156→/// Handle peer unsubscription
157→#[instrument(skip(state), fields(page_id = %state.page_id))]
158→pub async fn handle_unsubscribe(
159→    state: &mut ScribeState,
160→    user_did: &str,
161→    device_id: &str,
162→) {
163→    info!(user_did = %user_did, device_id = %device_id, "Peer unsubscribing");
164→
165→    // Save vectors from LayerUnit subscribers before removing
166→    let mut vectors: HashMap<String, Vec<u8>> = HashMap::new();
167→    for (layer_name, unit) in &state.units {
168→        if let Some(sub) = unit.remove_subscriber(user_did) {
169→            if !sub.version_vector.is_empty() {
170→                vectors.insert(layer_name.clone(), sub.version_vector);
171→            }
172→        }
173→    }
174→    if !vectors.is_empty() {
175→        if let Err(e) = state.vector_storage.save_vectors(user_did, device_id, &vectors) {
176→            warn!(error = %e, "Failed to save peer vectors on unsubscribe");
177→        }
178→    }
179→
180→    if let Ok(mut subs) = state.subscribers.write() {
181→        subs.remove(&(user_did.to_string(), device_id.to_string()));
182→        debug!(subscriber_count = subs.len(), "Subscriber removed");
183→    }
184→
185→    emit_peer_unsubscribed(state, user_did);
186→}
187→
188→/// Send initial state to a newly subscribed peer for layers they have access to
189→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
190→async fn send_initial_state_to_subscriber(
191→    state: &ScribeState,
192→    user_did: &str,
193→    device_id: &str,
194→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
195→) {
196→    let peer_vectors = match state.vector_storage.load_vectors(user_did, device_id) {
197→        Ok(Some(v)) => v.into_iter()
198→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
199→            .collect(),
200→        Ok(None) => HashMap::new(),
201→        Err(_) => HashMap::new(),
202→    };
203→
204→    for (layer_name, unit) in &state.units {
205→        // Only send to layers where subscriber was added
206→        if !unit.can_push_to(user_did) {
207→            continue;
208→        }
209→
210→        let layer = unit.layer();
211→
212→        let data = if let Some(their_vector) = peer_vectors.get(layer_name) {
213→            if their_vector.is_empty() {
214→                layer.export_snapshot()
215→            } else {
216→                match layer.export_updates(their_vector) {
217→                    Ok(updates) if updates.is_empty() => {
218→                        debug!(user_did = %user_did, layer = %layer_name, "No new updates");
219→                        continue;
220→                    }
221→                    Ok(updates) => updates,
222→                    Err(e) => {
223→                        warn!(error = %e, layer = %layer_name, "Failed incremental export, using snapshot");
224→                        layer.export_snapshot()
225→                    }
226→                }
227→            }
228→        } else {
229→            layer.export_snapshot()
230→        };
231→
232→        let state_vector = layer.version_vector();
233→
234→        if data.is_empty() || state_vector.len() <= 1 {
235→            debug!(user_did = %user_did, layer = %layer_name, "Skipping empty layer");
236→            continue;
237→        }
238→
239→        let payload = BroadcastPayload {
240→            page_id: state.page_id.clone(),
241→            layer_name: layer_name.clone(),
242→            layer_type: domains::LayerType::from_layer_name(layer_name),
243→            update: data,
244→            state_vector,
245→        };
246→
247→        if let Err(e) = broadcast_tx.try_send(payload) {
248→            warn!(user_did = %user_did, layer = %layer_name, error = %e, "Failed to send initial state");
249→        } else {
250→            debug!(user_did = %user_did, layer = %layer_name, "Sent initial state");
251→        }
252→    }
253→}
254→
255→/// Bootstrap __sync_meta for a newly subscribed peer (node-side)
256→///
257→/// **Context**: After a peer subscribes, the node creates their __sync_meta layer,
258→/// populates it with static layer entries, adds existing dynamic layer entries
259→/// for late joiners, and subscribes the peer to their __sync_meta layer.
260→#[instrument(skip(state, broadcast_tx), fields(page_id = %state.page_id, peer_did = %peer_did))]
261→fn bootstrap_sync_meta(
262→    state: &mut ScribeState,
263→    peer_did: &str,
264→    peer_permit: &gurkha::Permit,
265→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
266→) {
267→    use super::sync_meta;
268→
269→    // 1. Create __sync_meta:{peer_did} layer
270→    let meta_layer_name = sync_meta::ensure_sync_meta_layer(state, peer_did);
271→
272→    // 2. Populate with static layer entries
273→    let is_owner = peer_permit.relationship() == Some("owner");
274→    sync_meta::populate_static_layers(state, peer_did, peer_permit, is_owner);
275→
276→    // 3. Populate dynamic layers for late joiners
277→    sync_meta::populate_dynamic_layers_for_late_joiner(state, peer_did);
278→
279→    // 4. Subscribe the peer to their __sync_meta layer so it syncs to them
280→    if let Some(unit) = state.units.get(&meta_layer_name) {
281→        let caps = Capabilities { read: true, write: true, sync: true };
282→        unit.add_subscriber(peer_did.to_string(), caps, broadcast_tx.clone());
283→        info!(
284→            layer = %meta_layer_name,
285→            peer_did = %peer_did,
286→            "Subscribed peer to their __sync_meta layer"
287→        );
288→    }
289→}
