138→/// Simple glob pattern matching for layer names
139→///
140→/// **Supported patterns:**
141→/// - `*` at end: prefix match (e.g., "*:order" matches anything ending with ":order")
142→/// - `*` at start: suffix match (e.g., "did:*" matches anything starting with "did:")
143→/// - Exact match otherwise
144→pub fn glob_match(pattern: &str, name: &str) -> bool {
145→    if pattern == "*" {
146→        true
147→    } else if pattern.starts_with('*') {
148→        // Suffix match: "*:order" matches "did:key:abc:order"
149→        name.ends_with(&pattern[1..])
150→    } else if pattern.ends_with('*') {
151→        // Prefix match: "app:*" matches "app:shop"
152→        name.starts_with(&pattern[..pattern.len() - 1])
153→    } else {
154→        // Exact match
155→        pattern == name
156→    }
157→}
