183→            }
184→
185→            // Note: Derivation is now handled externally by kunki/LuaRuntime
186→            // which subscribes to PageUpdate::LayerChanged events
187→
188→            Ok(())
189→        }
190→        ApplyOutcome::Rejected { reason } => {
191→            warn!(layer = %layer_name, reason = %reason, "Update rejected");
192→            state.emit_apply_update_capture(layer_name, from_peer_did, "rejected", Some(&reason));
193→            Err(reason)
