  1→//! Apply update handling for Scribe actor
  2→//!
  3→//! Handles incoming layer updates (local or remote), including permission checks,
  4→//! validation, and CRDT merge.
  5→//!
  6→//! Note: Derivation is now handled externally by kunki/LuaRuntime which
  7→//! subscribes to PageUpdate::LayerChanged events.
  8→//!
  9→//! ## Key Types
 10→//!
 11→//! - `UpdateContext`: Computed context for an incoming update - all decisions made upfront
 12→//! - `ApplyOutcome`: Result of applying an update (Applied or Rejected)
 13→
 14→use logging_utils::ShortLayer;
 15→use tracing::{debug, error, info, warn, instrument};
 16→
 17→use domains::Layer;
 18→
 19→use super::broadcast::{broadcast_update, notify_layer_discovered};
 20→use crate::layer_unit::LayerUnit;
 21→use crate::loro_observer::{set_pending_update_source, clear_pending_update_source, setup_layer_observer};
 22→use crate::permit::{Permissions, PermitContext};
 23→use crate::state::ScribeState;
 24→use crate::JsonOp;
 25→use crate::state::normalize_layer_name;
 26→
 27→// Update Context - Centralized Decision Logic
 28→
 29→/// Context for an incoming update - computed once, used throughout
 30→///
 31→/// **Design**: All decisions about how to handle an update are computed upfront.
 32→/// This makes the apply flow clearer and easier to test.
 33→#[derive(Debug)]
 34→pub struct UpdateContext {
 35→    /// Layer being updated
 36→    pub layer_name: String,
 37→    /// Source of update: None = local, Some = remote peer (user_did, device_id)
 38→    pub from_peer: Option<(String, String)>,
 39→    /// Role of the peer (for validation) - "node", "owner", "viewer", etc.
 40→    pub peer_role: String,
 41→
 42→    /// Is this a remote update (from a peer)?
 43→    pub is_remote: bool,
 44→    /// Is this layer local-only (never synced)?
 45→    pub is_local_only: bool,
 46→    /// Does this update need Lua validation?
 47→    pub should_validate: bool,
 48→    /// Should we broadcast after applying?
 49→    pub should_broadcast: bool,
 50→    /// Is this a new layer (needs creation)?
 51→    pub is_new_layer: bool,
 52→}
 53→
 54→impl UpdateContext {
 55→    /// Create context for an incoming update
 56→    ///
 57→    /// **Context**: Computes all decisions based on state and update metadata
 58→    /// **Note**: Permission checks are done separately (may reject before context is useful)
 59→    pub fn new(
 60→        state: &ScribeState,
 61→        layer_name: &str,
 62→        from_peer: Option<(String, String)>,
 63→    ) -> Self {
 64→        let is_remote = from_peer.is_some();
 65→        let is_local_only = Permissions::is_local_only(layer_name);
 66→        let is_new_layer = !state.units.contains_key(layer_name);
 67→
 68→        // Determine peer role for validation
 69→        let peer_role = if let Some(ref peer) = from_peer {
 70→            get_peer_role(state, &peer.0)
 71→        } else {
 72→            "local".to_string()
 73→        };
 74→
 75→        // Should validate: remote update AND ValidationHandle exists
 76→        let should_validate = is_remote && state.validation_handle.is_some();
 77→
 78→        // Should broadcast: remote update (local updates use observer)
 79→        let should_broadcast = is_remote;
 80→
 81→        Self {
 82→            layer_name: layer_name.to_string(),
 83→            from_peer,
 84→            peer_role,
 85→            is_remote,
 86→            is_local_only,
 87→            should_validate,
 88→            should_broadcast,
 89→            is_new_layer,
 90→        }
 91→    }
 92→}
 93→
 94→// Apply Outcome - Event-Driven Pattern
 95→
 96→/// Outcome of applying an update
 97→///
 98→/// **Design**: Separates the "what happened" from "what to do next"
 99→/// This enables cleaner outcome handling and better error messages
100→#[derive(Debug)]
101→pub enum ApplyOutcome {
102→    /// Update was successfully applied
103→    Applied {
104→        /// Layer that was updated
105→        layer_name: String,
106→        /// Ops extracted from update (for derivation)
107→        ops: Vec<JsonOp>,
108→        /// Was a new layer created?
109→        created_layer: bool,
110→    },
111→    /// Update was rejected
112→    Rejected {
113→        /// Reason for rejection
114→        reason: String,
115→    },
116→}
117→
118→// Apply Update Handler
119→
120→/// Handle layer update (local or remote)
121→///
122→/// **Context**: Edit from UI or sync push from peer
123→/// **We do**: Permission check, validation, CRDT merge
124→/// **Broadcast**: Handled automatically by Loro observer (set up at startup)
125→/// **Returns**: Ok(()) on success, Err(message) on failure
126→#[instrument(skip(state, update, permit), fields(page_id = %state.page_id, layer = %ShortLayer(layer_name)))]
127→pub async fn handle_apply_update(
128→    state: &mut ScribeState,
129→    layer_name: &str,
130→    update: &[u8],
131→    from_peer: Option<(String, String)>,
132→    permit: Option<&str>,
133→) -> std::result::Result<(), String> {
134→    let _ = permit; // Permit is used for subscription in Courier, not here
135→
136→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
137→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
138→    let layer_name = layer_name.as_str();
139→
140→    // Build context - computes all decisions upfront
141→    let ctx = UpdateContext::new(state, layer_name, from_peer.clone());
142→
143→    // Step 1: Apply the update (with permission checks, validation, CRDT merge)
144→    let outcome = apply_update_core(state, &ctx, update).await;
145→
146→    // Step 2: Handle the outcome
147→    let from_peer_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str());
148→    match outcome {
149→        ApplyOutcome::Applied { layer_name, ops: _, created_layer } => {
150→            // Mark layer as dirty for persistence
151→            if let Some(unit) = state.units.get_mut(&layer_name) {
152→                unit.mark_dirty();
153→            }
154→            debug!(layer = %layer_name, created = created_layer, "Update applied successfully");
155→            state.emit_apply_update_capture(&layer_name, from_peer_did, "applied", None);
156→
157→            // Post-apply handling for remote updates
158→            if ctx.is_remote {
159→                handle_post_apply(state, &layer_name, ctx.from_peer.clone()).await;
160→            }
161→
162→            // Node-side: process __sync_meta updates to distribute layer discovery
163→            // When a creator's __sync_meta is updated, the node reads new entries and
164→            // writes them to other peers' __sync_meta (open grants → all, explicit → targeted)
165→            if ctx.is_remote {
166→                use super::sync_meta;
167→                if sync_meta::is_sync_meta_layer(&layer_name) {
168→                    if let Some(creator_did) = sync_meta::extract_peer_did(&layer_name) {
169→                        let creator_did = creator_did.to_string();
170→                        sync_meta::process_creator_sync_meta(state, &creator_did);
171→                    }
172→                }
173→            }
174→
175→            // Update sender's vector
176→            if let Some(ref peer) = ctx.from_peer {
177→                update_sender_vector(state, peer, &layer_name);
178→            }
179→
180→            // Broadcast to eligible subscribers
181→            if ctx.should_broadcast {
182→                broadcast_update(state, &layer_name, ctx.from_peer.as_ref()).await;
183→            }
184→
185→            // Note: Derivation is now handled externally by kunki/LuaRuntime
186→            // which subscribes to PageUpdate::LayerChanged events
187→
188→            Ok(())
189→        }
190→        ApplyOutcome::Rejected { reason } => {
191→            warn!(layer = %layer_name, reason = %reason, "Update rejected");
192→            state.emit_apply_update_capture(layer_name, from_peer_did, "rejected", Some(&reason));
193→            Err(reason)
194→        }
195→    }
196→}
197→
198→/// Core apply logic - returns ApplyOutcome
199→///
200→/// **Context**: Separated from handle_apply_update for cleaner testing
201→/// **Returns**: ApplyOutcome::Applied or ApplyOutcome::Rejected
202→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
203→async fn apply_update_core(
204→    state: &mut ScribeState,
205→    ctx: &UpdateContext,
206→    update: &[u8],
207→) -> ApplyOutcome {
208→    // Step 1: Permission check - reject local_only layers from remote
209→    if ctx.is_remote && ctx.is_local_only {
210→        return ApplyOutcome::Rejected {
211→            reason: "local_only layer cannot be updated by remote peer".to_string(),
212→        };
213→    }
214→
215→    // Step 2: Permission check for remote updates
216→    if let Some(ref peer) = ctx.from_peer {
217→        if !Permissions::can_write(state, peer, &ctx.layer_name) {
218→            return ApplyOutcome::Rejected {
219→                reason: "Permission denied: cannot write to layer".to_string(),
220→            };
221→        }
222→    }
223→
224→    // Step 3: Extract ops for validation (using optimized pre-commit method)
225→    let extracted_ops = if ctx.should_validate {
226→        // Use Layer::extract_ops_from_bytes (5-10x faster than old fork+diff)
227→        match Layer::extract_ops_from_bytes(update) {
228→            Ok(ops) => Some(ops),
229→            Err(e) => {
230→                // Log extraction failure - validation will proceed with empty ops
231→                // This could mask invalid updates, so log at warn level
232→                warn!(layer = %ctx.layer_name, error = %e, "Failed to extract ops from update, proceeding with empty ops");
233→                None
234→            }
235→        }
236→    } else {
237→        None
238→    };
239→
240→    // Step 4: Validate with Lua (if needed)
241→    if ctx.should_validate {
242→        if let Err(e) = validate_update_with_context(state, ctx, &extracted_ops).await {
243→            return ApplyOutcome::Rejected { reason: e };
244→        }
245→    }
246→
247→    // Step 5: Create layer if needed (remote only)
248→    let created_layer = if ctx.is_new_layer {
249→        if ctx.is_remote {
250→            create_layer_from_peer(state, &ctx.layer_name);
251→            true
252→        } else {
253→            return ApplyOutcome::Rejected {
254→                reason: "Layer not found".to_string(),
255→            };
256→        }
257→    } else {
258→        false
259→    };
260→
261→    // Step 6: Apply CRDT update
262→    if let Err(e) = apply_crdt_update(state, &ctx.layer_name, update, ctx.from_peer.clone()) {
263→        return ApplyOutcome::Rejected { reason: e };
264→    }
265→
266→    ApplyOutcome::Applied {
267→        layer_name: ctx.layer_name.clone(),
268→        ops: extracted_ops.unwrap_or_default(),
269→        created_layer,
270→    }
271→}
272→
273→// Helper Functions
274→
275→/// Validate update using ValidationHandle (kunki) or fallback to Lua runtime
276→///
277→/// **Context**: Business logic validation for remote updates
278→/// **Returns**: Ok(()) if validation passed, Err(message) if rejected
279→/// **Timeout**: 5 seconds for ValidationHandle (kunki), immediate for Lua runtime
280→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
281→async fn validate_update_with_context(
282→    state: &ScribeState,
283→    ctx: &UpdateContext,
284→    extracted_ops: &Option<Vec<JsonOp>>,
285→) -> Result<(), String> {
286→    let Some(ref ops) = extracted_ops else {
287→        return Ok(()); // No ops to validate
288→    };
289→
290→    if ops.is_empty() {
291→        return Ok(()); // Empty ops = nothing to validate
292→    }
293→
294→    // Extract actual DID from from_peer, not the role
295→    let from_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str()).unwrap_or("local");
296→
297→    // Use ValidationHandle (kunki mode with presence_lib)
298→    let Some(ref validation_handle) = state.validation_handle else {
299→        // No validation available - allow update (viewer/owner mode without kunki)
300→        // This is expected in viewer/owner mode but unexpected in node mode without kunki
301→        warn!(layer = %ctx.layer_name, from_did = %from_did, "No ValidationHandle available, allowing remote update without validation");
302→        return Ok(());
303→    };
304→
305→    use tokio::time::{timeout, Duration};
306→
307→    let validation_future = validation_handle.validate_ops(
308→        &state.page_id,
309→        &ctx.layer_name,
310→        ops,
311→        from_did,
312→        &ctx.peer_role,
313→    );
314→
315→    match timeout(Duration::from_secs(5), validation_future).await {
316→        Ok(Ok((true, _))) => {
317→            debug!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, "Validation passed");
318→            Ok(())
319→        }
320→        Ok(Ok((false, error_msg))) => {
321→            let msg = error_msg.unwrap_or_else(|| "Validation failed".to_string());
322→            warn!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, error = %msg, "Validation rejected update");
323→            Err(format!("Validation failed: {}", msg))
324→        }
325→        Ok(Err(e)) => {
326→            warn!(layer = %ctx.layer_name, error = %e, "Validation error, rejecting update");
327→            Err(format!("Validation error: {}", e))
328→        }
329→        Err(_) => {
330→            warn!(layer = %ctx.layer_name, "Validation timeout (5s), rejecting update");
331→            Err("Validation timeout".to_string())
332→        }
333→    }
334→}
335→
336→/// Create a new layer from peer sync
337→///
338→/// **Context**: Peer sent update for a layer we don't have yet
339→/// **We do**: Create layer, set up observer, notify UI
340→#[instrument(skip(state), fields(page_id = %state.page_id))]
341→fn create_layer_from_peer(state: &mut ScribeState, layer_name: &str) {
342→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
343→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
344→    let layer_name = layer_name.as_str();
345→    let mut unit = LayerUnit::new_empty();
346→    unit.set_local_only(!state.should_sync_layer(layer_name));
347→    unit.mark_dirty();
348→    state.units.insert(layer_name.to_string(), unit);
349→    info!(layer = %layer_name, "Created new layer from peer sync");
350→
351→    // Add existing subscribers to this new layer
352→    if let Ok(subs) = state.subscribers.read() {
353→        for ((did, _), info) in subs.iter() {
354→            if info.can_receive_layer(layer_name, &state.page_id) {
355→                if let Some(unit) = state.units.get(layer_name) {
356→                    let can_write = info.can_write_layer(layer_name, &state.page_id);
357→                    let caps = crate::layer_unit::Capabilities { read: true, write: can_write, sync: true };
358→                    unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
359→                    state.emit_layer_auth_capture(layer_name, did, "subscriber_added_from_peer");
360→                }
361→            }
362→        }
363→    }
364→
365→    // Set up Loro observer for new layer to enable sync broadcasts
366→    setup_layer_observer(state, layer_name);
367→
368→    // Notify UI subscribers about the new layer
369→    notify_layer_discovered(state, layer_name);
370→}
371→
372→/// Apply CRDT update to layer
373→///
374→/// **Context**: Actually merge the update into the layer
375→/// **We do**: Set pending source, apply, clear pending source
376→#[instrument(skip(state, update), fields(page_id = %state.page_id, layer = %layer_name))]
377→fn apply_crdt_update(
378→    state: &mut ScribeState,
379→    layer_name: &str,
380→    update: &[u8],
381→    from_peer: Option<(String, String)>,
382→) -> Result<(), String> {
383→    // Set pending update source BEFORE apply() so observer knows who caused this change
384→    set_pending_update_source(state, from_peer);
385→
386→    // Get the layer and apply update
387→    let result = if let Some(unit) = state.units.get(layer_name) {
388→        unit.layer().apply(update)
389→    } else {
390→        clear_pending_update_source(state);
391→        return Err("Layer not found".to_string());
392→    };
393→
394→    if let Err(e) = result {
395→        // Clear on error too
396→        clear_pending_update_source(state);
397→        error!(error = %e, "Failed to apply update to layer");
398→        return Err(format!("Failed to apply update: {}", e));
399→    }
400→
401→    // Clear pending update source AFTER apply() (observer already captured it)
402→    clear_pending_update_source(state);
403→
404→    Ok(())
405→}
406→
407→/// Handle post-apply actions for remote updates
408→///
409→/// **Context**: Remote update was successfully applied
410→/// **We do**: Flush app layers immediately
411→/// **Note**: UI notification is handled by Loro observer (no duplicate emit here)
412→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
413→async fn handle_post_apply(
414→    state: &mut ScribeState,
415→    layer_name: &str,
416→    _from_peer: Option<(String, String)>,
417→) {
418→    // For app layers, flush immediately to storage so restart loads new code
419→    if layer_name.starts_with("app:") {
420→        if let Some(unit) = state.units.get_mut(layer_name) {
421→            let snapshot = unit.layer().export_snapshot();
422→            if let Err(e) = state.layer_storage.save_layer(layer_name, &snapshot) {
423→                error!(layer = %layer_name, error = %e, "Failed to save app layer immediately");
424→            } else {
425→                info!(layer = %layer_name, "Saved app layer immediately for restart");
426→                // Remove from dirty since we just saved it
427→                unit.clear_dirty();
428→            }
429→        }
430→    }
431→
432→    // Note: UI notification via emit_layer_changed_after_apply was removed
433→    // The Loro observer handles PageUpdate::LayerChanged for all changes (local and remote)
434→    // This prevents duplicate notifications
435→}
436→
437→/// Update sender's peer vector after receiving their update
438→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
439→fn update_sender_vector(state: &mut ScribeState, peer: &(String, String), layer_name: &str) {
440→    if let Some(unit) = state.units.get(layer_name) {
441→        if let Ok(mut subs) = state.subscribers.write() {
442→            if let Some(info) = subs.get_mut(peer) {
443→                let current_vector = unit.layer().version_vector();
444→                info.vectors.insert(layer_name.to_string(), current_vector);
445→                debug!(user_did = %peer.0, "Updated sender's peer vector");
446→            }
447→        }
448→    }
449→}
450→
451→/// Get role for a peer from their stored permit
452→///
453→/// **Context**: Determining role for Lua validation
454→/// **Checks**:
455→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
456→/// 2. Stored permit (node mode) -> extract role from permit
457→/// 3. Default -> "peer"
458→#[instrument(skip(state), fields(page_id = %state.page_id))]
459→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
460→    // If peer is our sync target, they are the "node" from our perspective
461→    if let Some(ref config) = state.sync_config {
462→        if let Some(ref sync_target) = config.sync_target {
463→            if sync_target == peer_did {
464→                return "node".to_string();
465→            }
466→        }
467→    }
468→
469→    // Node mode: look up peer's stored permit and extract role via PermitContext
470→    if let Some(ref resolver) = state.peer_resolver {
471→        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
472→            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
473→                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
474→                .unwrap_or_else(|_| "peer".to_string());
475→            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
476→            return role;
477→        }
478→    }
479→
480→    // Default role
481→    "peer".to_string()
482→}
483→

